const {chromium}=require('playwright');const F='file://'+process.argv[2];const S=process.argv[3];
const ok=(c,m)=>console.log((c?'PASS ':'FAIL ')+m);
(async()=>{const b=await chromium.launch();const p=await b.newPage({viewport:{width:1440,height:900}});const e=[];p.on('pageerror',x=>e.push(x.message));
await p.goto(F);await p.evaluate(()=>localStorage.clear());await p.reload();await p.waitForTimeout(500);
await p.screenshot({path:S+'/vid-fold.png'});
await p.evaluate(()=>document.getElementById('player').scrollIntoView({block:'center'}));await p.waitForTimeout(3200);
ok((await p.textContent('#v-typed')).length>20,'prompt types itself');
await p.screenshot({path:S+'/vid-s0.png'});
await p.click('.seg2[data-scene="1"]');await p.waitForTimeout(3300);
ok(await p.locator('#cam.zoom').count()===1,'camera zooms in');ok(await p.locator('#v-opt.on').count()===1,'cursor picks the answer');
await p.screenshot({path:S+'/vid-s1.png'});
await p.click('.seg2[data-scene="3"]');await p.waitForTimeout(3000);
ok(await p.locator('#v-fix.fixed').count()===1,'40% replaced');await p.screenshot({path:S+'/vid-s3.png'});
await p.click('.seg2[data-scene="4"]');await p.waitForTimeout(1500);ok(await p.locator('#player.agreed').count()===1,'agree scene');
await p.click('#v-play');ok((await p.textContent('#v-play'))==='▶','pause works');
await p.click('[data-ps="solution"]');await p.waitForTimeout(1300);ok(await p.locator('.bcard.in').count()===4,'solution tree appears');
await p.locator('.ps').screenshot({path:S+'/vid-ps.png'});
const m=await b.newPage({viewport:{width:390,height:844}});await m.goto(F);await m.waitForTimeout(500);
ok(!(await m.evaluate(()=>document.documentElement.scrollWidth>innerWidth)),'fits a phone');
ok(e.length===0,'no errors '+e.join('; '));await b.close();})();
